// Google Drive's Download node stores the file under a binary property whose
// .data field is already base64 in n8n's default binary storage mode.
const prop = Object.keys($input.item.binary || {})[0] || 'data';
const bin = $input.item.binary[prop];
if (!bin || !bin.data) throw new Error(`No binary data under "${prop}" — check the Download node's binary property name.`);
const mime = bin.mimeType || 'application/pdf';
return [{ json: {
  base64: bin.data, mimeType: mime, isPdf: mime.includes('pdf'),
  fileName: bin.fileName || 'contract',
  fileId: $('Retrieve Contract from Drive').first().json.id
          || $('Configure Review Settings').first().json.testFileId || '',
} }];

const f = $json;
const cfg = $('Configure Review Settings').first().json;
const block = f.isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: f.base64 } }
  : { type: 'image', source: { type: 'base64', media_type: f.mimeType || 'image/jpeg', data: f.base64 } };
return [{ json: {
  model: cfg.anthropicModel || 'claude-sonnet-4-6',
  max_tokens: 8000,
  system: cfg.extractionSystemPrompt,
  messages: [{ role: 'user', content: [block, { type: 'text', text: 'Extract the clauses as JSON.' }] }],
} }];

// A parse failure here is fatal for the run rather than something to route
// around: with no clauses there is nothing to assess, and silently continuing
// would produce an empty "no issues found" report — the most dangerous
// possible output for a contract review.
const src = $('Encode File to Base64').first().json;
let text = '';
try { text = ($json.content || []).map(b => b.text || '').join('').trim(); } catch (e) {}

let data = null;
try { data = JSON.parse(text.replace(/```json|```/gi, '').trim()); }
catch (e) { throw new Error(`Could not parse the extraction response: ${e.message}. First 300 chars: ${text.slice(0, 300)}`); }

const clauses = Array.isArray(data.clauses) ? data.clauses : [];
if (!clauses.length) {
  throw new Error(`No clauses extracted. Model said: ${data.extraction_notes || '(no note)'}`);
}

return clauses.map((c, i) => ({ json: {
  clause_id: c.clause_id || `C${i + 1}`,
  heading: c.heading || '', topic: c.topic || 'other',
  summary: c.summary || '', verbatim_key_sentence: c.verbatim_key_sentence || '',
  contract_type: data.contract_type || '', parties: (data.parties || []).join(' | '),
  governing_law: data.governing_law || '', effective_date: data.effective_date || '',
  term_description: data.term_description || '',
  file_name: src.fileName, file_id: src.fileId,
  total_clauses: clauses.length,
} }));

options.systemMessage:
=You assess ONE contract clause against the reviewing party's standard negotiating positions. You are not a lawyer and your output is a first-pass triage for one, not legal advice.

=== WHOSE SIDE YOU ARE ON ===
{{ $('Configure Review Settings').first().json.ourSide }}

=== OUR STANDARD POSITIONS (the playbook) ===
{{ $('Configure Review Settings').first().json.playbook }}

=== HARD LIMITS (any clause breaching one of these is automatically a blocker) ===
{{ $('Configure Review Settings').first().json.hardLimits }}

=== THE CLAUSE ===
Topic: {{ $json.topic }}
Heading: {{ $json.heading }}
Summary: {{ $json.summary }}
Key sentence: {{ $json.verbatim_key_sentence }}

RULES
- Judge only this clause. You cannot see the others, so never assume what they say.
- `position` compares the clause to the playbook, not to what you personally think is fair.
- A clause that is silent on something the playbook requires is a real finding — report it as `missing_protection`, not as acceptable.
- `suggested_redline` should be a concrete replacement or addition a lawyer could edit, not a description of what to change.
- If the clause text is too fragmentary to assess, set position to "unclear" and say what is missing. That is a useful answer.
- Never state that something is legal, enforceable, or compliant in a given jurisdiction. That judgement belongs to a qualified lawyer.

parameters.jsCode:
const a = $json.output ?? $json;
const c = $('Batch Process Clauses').first().json;
return [{ json: {
  ...c,
  position: a.position ?? 'unclear',
  severity: a.severity ?? 'low',
  breaches_hard_limit: !!a.breaches_hard_limit,
  which_hard_limit: a.which_hard_limit ?? '',
  explanation: a.explanation ?? '',
  business_impact: a.business_impact ?? '',
  suggested_redline: a.suggested_redline ?? '',
  question_for_counsel: a.question_for_counsel ?? '',
} }];

// Runs once, on the loop's "done" output. Every assessed clause arrives here
// as a separate item, so this is the only place with the whole picture.
const items = $input.all().map(i => i.json);
const cfg = $('Configure Review Settings').first().json;

const RANK = { blocker: 4, high: 3, medium: 2, low: 1, none: 0 };
const counts = { blocker: 0, high: 0, medium: 0, low: 0, none: 0 };
items.forEach(i => { counts[i.severity] = (counts[i.severity] || 0) + 1; });

const hardLimitBreaches = items.filter(i => i.breaches_hard_limit);
const worst = items.reduce((m, i) => Math.max(m, RANK[i.severity] ?? 0), 0);

// Deterministic verdict. A hard-limit breach governs regardless of how the
// individual clause was scored — the playbook's limits are the whole point of
// having a playbook, and no per-clause judgement overrides them.
let verdict;
if (hardLimitBreaches.length) verdict = 'DO_NOT_SIGN';
else if (worst >= 4) verdict = 'DO_NOT_SIGN';
else if (worst === 3) verdict = 'NEGOTIATE_BEFORE_SIGNING';
else if (worst === 2) verdict = 'SIGN_WITH_NOTED_RISKS';
else verdict = 'CLEAN';

const head = items[0] || {};
return [{ json: {
  file_name: head.file_name || '', file_id: head.file_id || '',
  contract_type: head.contract_type || '', parties: head.parties || '',
  governing_law: head.governing_law || '', effective_date: head.effective_date || '',
  term_description: head.term_description || '',
  clauses_assessed: items.length,
  count_blocker: counts.blocker, count_high: counts.high,
  count_medium: counts.medium, count_low: counts.low,
  hard_limit_breaches: hardLimitBreaches.map(i => `${i.clause_id} (${i.which_hard_limit})`).join(' | '),
  verdict,
  needs_human: verdict !== 'CLEAN'
               || Number(cfg.alwaysEscalate === 'true' ? 1 : 0) === 1,
  findings: items.map(i => ({
    clause_id: i.clause_id, heading: i.heading, topic: i.topic,
    position: i.position, severity: i.severity,
    breaches_hard_limit: i.breaches_hard_limit, which_hard_limit: i.which_hard_limit,
    explanation: i.explanation, business_impact: i.business_impact,
    suggested_redline: i.suggested_redline, question_for_counsel: i.question_for_counsel,
    verbatim_key_sentence: i.verbatim_key_sentence,
  })),
} }];

const p = $json;
const url = $execution.resumeUrl;
const blockers = (p.findings || []).filter(f => f.severity === 'blocker' || f.breaches_hard_limit);
const L = [
  `📄 Contract review — ${p.verdict}`,
  `${p.file_name || 'contract'}${p.contract_type ? ' · ' + p.contract_type : ''}`,
  `${p.clauses_assessed} clauses assessed · ${p.count_blocker} blocker, ${p.count_high} high, ${p.count_medium} medium`,
];
if (p.hard_limit_breaches) L.push(`⛔ Hard limits breached: ${p.hard_limit_breaches}`);
if (blockers.length) {
  L.push('');
  blockers.slice(0, 5).forEach(b => L.push(`• ${b.clause_id} ${b.heading}: ${b.explanation}`));
}
L.push('');
L.push(`✅ Reviewed, proceed → ${url}?decision=PROCEED`);
L.push(`✏️ Sending for redlining → ${url}?decision=REDLINE`);
L.push(`⛔ Rejecting this contract → ${url}?decision=REJECT`);
return [{ json: { ...p, escalation_text: L.join('\n') } }];

// Rebuilds from the escalation node rather than trusting the resumed payload's
// shape. If clicking a link does not register, this is the first node to open:
// n8n delivers query params under $json.query or $json.body depending on
// version, so both are checked, defaulting to the cautious REDLINE.
const p = $('Craft Escalation Notice').first().json;
const raw = ($json.query && $json.query.decision) || ($json.body && $json.body.decision) || 'REDLINE';
const d = String(raw).toUpperCase();
const valid = ['PROCEED', 'REDLINE', 'REJECT'];
return [{ json: { ...p, reviewer_decision: valid.includes(d) ? d : 'REDLINE' } }];

const p = $json;
const ICON = { CLEAN: '🟢', SIGN_WITH_NOTED_RISKS: '🟡',
               NEGOTIATE_BEFORE_SIGNING: '🟠', DO_NOT_SIGN: '🔴' };
const ORDER = { blocker: 0, high: 1, medium: 2, low: 3, none: 4 };

const L = [];
L.push(`${ICON[p.verdict] || '•'} **${p.verdict}** · reviewer: ${p.reviewer_decision}`);
L.push(`### ${p.file_name || 'Contract'}`);
[['Type', p.contract_type], ['Parties', p.parties], ['Governing law', p.governing_law],
 ['Effective', p.effective_date], ['Term', p.term_description]]
  .forEach(([k, v]) => { if (v) L.push(`**${k}:** ${v}`); });
L.push('');
L.push(`${p.clauses_assessed} clauses assessed — ${p.count_blocker} blocker, ${p.count_high} high, ${p.count_medium} medium, ${p.count_low} low.`);
if (p.hard_limit_breaches) { L.push(''); L.push(`⛔ **Hard limits breached:** ${p.hard_limit_breaches}`); }

const sorted = [...(p.findings || [])].sort((a, b) => (ORDER[a.severity] ?? 9) - (ORDER[b.severity] ?? 9));
sorted.filter(f => f.severity !== 'none').forEach(f => {
  L.push('');
  L.push(`---`);
  L.push(`**${f.clause_id} · ${f.heading || f.topic}** — ${f.severity.toUpperCase()} · ${f.position}`);
  if (f.explanation) L.push(f.explanation);
  if (f.business_impact) L.push(`*Impact:* ${f.business_impact}`);
  if (f.verbatim_key_sentence) L.push(`> ${f.verbatim_key_sentence}`);
  if (f.suggested_redline) { L.push(''); L.push(`**Suggested redline:** ${f.suggested_redline}`); }
  if (f.question_for_counsel) L.push(`**Ask counsel:** ${f.question_for_counsel}`);
});

L.push('');
L.push('---');
L.push('*First-pass triage produced automatically. Not legal advice — a qualified lawyer should review anything before it is signed.*');

return [{ json: { ...p, report: L.join('\n'),
  completed_at: new Date().toISOString().slice(0, 19).replace('T', ' ') } }];

const p = $json;
return [{ json: {
  completed_at: p.completed_at || '', file_name: p.file_name || '', file_id: p.file_id || '',
  contract_type: p.contract_type || '', parties: p.parties || '',
  governing_law: p.governing_law || '', effective_date: p.effective_date || '',
  verdict: p.verdict || '', reviewer_decision: p.reviewer_decision || '',
  clauses_assessed: p.clauses_assessed ?? '',
  count_blocker: p.count_blocker ?? '', count_high: p.count_high ?? '',
  count_medium: p.count_medium ?? '', count_low: p.count_low ?? '',
  hard_limit_breaches: p.hard_limit_breaches || '',
  report: p.report || '',
} }];
